set +e
S="ssh -o BatchMode=yes -o StrictHostKeyChecking=no rowan-dev"
$S "echo  | base64 -d > /tmp/socks5.py; nohup python3 /tmp/socks5.py 13389 >/tmp/socks5.log 2>&1 & sleep 2; ss -tln | grep 13389; cat /tmp/socks5.log"
ssh -f -N -o BatchMode=yes -o ExitOnForwardFailure=yes -L 1080:127.0.0.1:13389 rowan-dev
sleep 2
echo "--- SOCKS test ---"
curl -sS -m 8 -k --socks5-hostname 127.0.0.1:1080 -o /dev/null -w "source=%{http_code}\n" https://source.keplerops.test/
curl -sS -m 8 -k --socks5-hostname 127.0.0.1:1080 -o /dev/null -w "arwc=%{http_code}\n" https://connector.arwc.test/
curl -sS -m 8 -k --socks5-hostname 127.0.0.1:1080 -o /dev/null -w "staff=%{http_code}\n" https://staff.keplerops.test/
pkill -f "1080:127.0.0.1:13389"
$S "pkill -f 'python3 /tmp/socks5.py'"
echo cleaned
